INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5dad4636-e6d9-4374-a729-d4ea67ee24fd', '1', 'anestesico_amida', 'Lidocaína 2% + Epinefrina 1:100.000', NULL, 'Tubos 1.8 ml (36 mg lidocaína + 0.018 mg epinefrina)', 'Anestesia infiltrativa o troncular. Máximo 7 tubos en adulto sano (500 mg). Dosis máx: 7 mg/kg con vasoconstrictor.', 'Dosis máx: 4-5 mg/kg. Calcular: 0.05 ml/kg por tubo. Ej: niño 20 kg → máx 2 tubos.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas (muy rara), arritmias no controladas, hipertiroidismo no controlado', '[]'::jsonb, NULL, TRUE, TRUE, 'Anestésico de elección en la mayoría de procedimientos. Duración pulpar 60 min, tejidos blandos 3-5 h', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('09a3caca-9aad-4224-8590-cce6aaa3e470', '2', 'anestesico_amida', 'Lidocaína 2% + Epinefrina 1:200.000', NULL, 'Tubos 1.8 ml (36 mg lidocaína + 0.009 mg epinefrina)', 'Anestesia infiltrativa o troncular. Máximo 7 tubos en adulto sano. Preferida en cardiopatías por menor dosis de epinefrina.', 'Dosis máx: 4-5 mg/kg. Calcular: 0.05 ml/kg. Ej: niño 20 kg → máx 2 tubos.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Igual que Lidocaína 1:100.000', '[]'::jsonb, NULL, TRUE, TRUE, 'Alternativa en pacientes con riesgo cardiovascular por menor carga adrenérgica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a0e59092-f427-46d5-b5c1-8cfeaf619704', '3', 'anestesico_amida', 'Mepivacaína 3% sin vasoconstrictor', NULL, 'Tubos 1.8 ml (54 mg mepivacaína)', 'Anestesia infiltrativa o troncular. Máximo 4 tubos en adulto sano (300 mg). Dosis máx: 4.4 mg/kg.', 'Dosis máx: 4 mg/kg. Calcular: 0.03 ml/kg. Ej: niño 20 kg → máx 1.5 tubos.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas', '[]'::jsonb, NULL, TRUE, TRUE, 'Anestésico de elección en hipertensos no controlados y cardiopatías graves por ausencia de vasoconstrictor. Menor duración pulpar (20-40 min)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('4e42d663-97bd-488e-9d5b-d080cd34f79a', '4', 'anestesico_amida', 'Mepivacaína 2% + Levonordefrina 1:20.000', NULL, 'Tubos 1.8 ml (36 mg mepivacaína + 0.09 mg levonordefrina)', 'Anestesia infiltrativa o troncular. Máximo 4 tubos. Dosis máx: 4.4 mg/kg.', 'Dosis máx: 4 mg/kg.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas', '[]'::jsonb, NULL, TRUE, TRUE, 'Levorotatorio de noradrenalina, útil como alternativa a epinefrina', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('cd29b6ce-00dd-4154-ab70-1896f18e57e6', '5', 'anestesico_amida', 'Articaína 4% + Epinefrina 1:100.000', NULL, 'Tubos 1.8 ml (72 mg articaína + 0.018 mg epinefrina)', 'Anestesia de alta difusibilidad ósea. Ideal para infiltrativa mandibular y endodoncias. Máximo 5 tubos (500 mg). Dosis máx: 7 mg/kg.', 'Dosis máx: 5 mg/kg. Calcular: 0.035 ml/kg. Ej: niño 20 kg → máx 1.5 tubos.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas', '[]'::jsonb, NULL, TRUE, TRUE, 'Mayor potencia anestésica por mejor difusión ósea. Preferida en endodoncia de molares inferiores', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('9b65daba-c8b7-4a19-a481-373a4e0d0cfc', '6', 'anestesico_amida', 'Articaína 4% + Epinefrina 1:200.000', NULL, 'Tubos 1.8 ml (72 mg articaína + 0.009 mg epinefrina)', 'Anestesia de alta difusibilidad ósea. Máximo 5 tubos. Dosis máx: 7 mg/kg.', 'Dosis máx: 5 mg/kg.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas', '[]'::jsonb, NULL, TRUE, TRUE, 'Alternativa con menor carga adrenérgica para pacientes con riesgo cardiovascular', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('8b04f846-b520-44a4-af8e-ba634378bbbb', '7', 'anestesico_amida', 'Bupivacaína 0.5% + Epinefrina 1:200.000', NULL, 'Tubos 1.8 ml (9 mg bupivacaína + 0.009 mg epinefrina)', 'Anestesia de larga duración para cirugías complejas y manejo de dolor postquirúrgico. Máximo 2 tubos. Dosis máx: 2 mg/kg.', 'Dosis máx: 1.5 mg/kg. Calcular: 0.09 ml/kg.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a amidas, cardiopatías graves', '[]'::jsonb, NULL, TRUE, TRUE, 'Duración pulpar hasta 90 min y tejidos blandos 8-12 h. Riesgo de mordedura post-anestesia en niños - evitar en pediátrica si es posible', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('09b60dbd-05ec-4b06-a7e6-7225070a732b', '8', 'anestesico_topico', 'Benzocaína 20% tópico', NULL, 'Gel/spray 20% (frasco 30-60 ml)', 'Aplicar con hisopo o spray sobre mucosa 1-2 min antes de la inyección. Máximo 2 aplicaciones por sesión.', 'Evitar en menores de 2 años por riesgo de metahemoglobinemia. En mayores de 2 años: aplicación mínima necesaria.', NULL, NULL, NULL, NULL, NULL, 'Dosis única por sesión', 'Hipersensibilidad a anestésicos tipo éster, metahemoglobinemia', '[]'::jsonb, NULL, TRUE, TRUE, 'Anestésico tipo éster. Riesgo raro de metahemoglobinemia. No usar en heridas extensas', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('537edb5c-5122-4729-a228-747a594833be', '9', 'paracetamol', 'Paracetamol 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1-2 comprimidos cada 6-8 horas (500-1000 mg/dosis). Máximo 4 g/día en adulto sano (reducir a 3 g/día en hepatopatía o consumo de alcohol).', 'Niños: 10-15 mg/kg/dosis cada 6 horas. Suspensión 160 mg/5 ml: 2.5 ml por cada 10 kg de peso. Máximo 60 mg/kg/día.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Insuficiencia hepática grave, hipersensibilidad', '[]'::jsonb, NULL, TRUE, TRUE, 'Analgésico de elección en pacientes anticoagulados, embarazadas y con contraindicación de AINEs. No tiene efecto antiinflamatorio', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d999b350-135d-4434-9602-cfa13fb7e192', '10', 'paracetamol', 'Paracetamol 1 g', NULL, 'Comprimidos 1000 mg', 'Tomar 1 comprimido cada 8 horas (3 g/día). Máximo 4 g/día. Alternar con AINEs para efecto sinérgico.', 'No usar comprimido 1 g en niños <40 kg. Usar presentación pediátrica.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Insuficiencia hepática grave', '[]'::jsonb, NULL, TRUE, TRUE, 'Presentación de elección en adulto. Combinar con Ibuprofeno 400 mg para dolor post-exodoncia', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('ff1d6c71-c9e0-4290-9816-5eb69b8e5c15', '11', 'paracetamol', 'Paracetamol suspensión 160 mg/5 ml', NULL, 'Frasco jarabe 160 mg/5 ml (100 ml)', 'No usar en adultos (dosis insuficiente)', 'Niños: 10-15 mg/kg/dosis cada 6 horas. Fórmula: 0.3 ml/kg/dosis. Ej: niño 15 kg → 4.5 ml. Máximo 4 dosis/día.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Insuficiencia hepática grave', '[]'::jsonb, NULL, TRUE, TRUE, 'Presentación pediátrica de elección. Agitar bien antes de usar. Medir con jeringa dosificadora', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('e4d869c2-be1a-4afa-9d23-ecc805142980', '12', 'aine', 'Ibuprofeno 400 mg', NULL, 'Comprimidos 400 mg / Suspensión 100 mg/5 ml', 'Tomar 1 comprimido cada 6-8 horas con alimentos (máximo 2.4 g/día). Primera elección para dolor odontogénico leve a moderado. Combinar con Paracetamol 1 g para efecto sinérgico.', 'Niños 6 meses-12 años: 5-10 mg/kg/dosis cada 6-8 horas. Suspensión 100 mg/5 ml: 2.5 ml por cada 10 kg de peso, 3-4 veces/día. Máximo 40 mg/kg/día.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Úlcera péptica activa, insuficiencia renal/hepática grave, asma inducida por AINEs, 3er trimestre embarazo, pacientes anticoagulados (preferir Paracetamol)', '[]'::jsonb, NULL, TRUE, TRUE, 'AINE de primera línea en odontología. Eficacia comparable a opioides con menor riesgo. Tomar siempre con alimentos', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5c079918-3123-4fc0-b4a5-79b0bafac843', '13', 'aine', 'Ibuprofeno 600 mg', NULL, 'Comprimidos 600 mg', 'Tomar 1 comprimido cada 8 horas con alimentos (máximo 2.4 g/día). Para dolor post-quirúrgico moderado a severo.', 'No usar comprimido 600 mg en niños <40 kg. Usar presentación pediátrica.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Igual que Ibuprofeno 400 mg', '[]'::jsonb, NULL, TRUE, TRUE, 'Dosis de elección post-exodoncia en adultos sin contraindicaciones', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('ca659c61-edf5-4d08-b5b1-901f5b2f9db4', '14', 'aine', 'Ibuprofeno suspensión 100 mg/5 ml', NULL, 'Frasco jarabe 100 mg/5 ml (100 ml)', 'No usar en adultos (dosis insuficiente)', 'Niños 6 meses-12 años: 5-10 mg/kg/dosis cada 6-8 horas. Fórmula: 0.3 ml/kg/dosis. Ej: niño 15 kg → 4.5 ml. Máximo 40 mg/kg/día.', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Igual que Ibuprofeno 400 mg', '[]'::jsonb, NULL, TRUE, TRUE, 'Presentación pediátrica de elección. Agitar bien. Medir con jeringa dosificadora', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('10436bdd-86cf-4d81-89a0-baa09530634c', '15', 'aine', 'Ketoprofeno 100 mg', NULL, 'Comprimidos 100 mg', 'Tomar 1 comprimido cada 12 horas con alimentos (máximo 200 mg/día). Alternativa a Ibuprofeno en dolor post-quirúrgico.', 'No recomendado en menores de 15 años (usar Ibuprofeno).', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Igual que otros AINEs clásicos', '[]'::jsonb, NULL, TRUE, TRUE, 'Potencia analgésica superior a Ibuprofeno. Mayor riesgo GI - siempre con alimentos y máxima duración 5 días', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('1ab11ee6-4a55-4bd3-8d46-3db8f2152297', '16', 'aine', 'Diclofenaco sódico 50 mg', NULL, 'Comprimidos 50 mg', 'Tomar 1 comprimido cada 8-12 horas con alimentos (máximo 150 mg/día).', 'No recomendado en menores de 12 años (usar Ibuprofeno).', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Igual que otros AINEs clásicos. Contraindicado en insuficiencia cardíaca congestiva', '[]'::jsonb, NULL, TRUE, TRUE, 'AINE de segunda línea. Perfil GI similar a Ibuprofeno', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('36fc2eaf-daaf-44ff-a28c-55b66af753aa', '17', 'aine', 'Ketorolaco 10 mg sublingual', NULL, 'Comprimidos sublinguales 10 mg', 'Disolver 1 comprimido bajo la lengua cada 8 horas (máximo 40 mg/día). Para dolor agudo severo post-quirúrgico.', 'Contraindicado en menores de 16 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 2 días (oral) / 5 días (inyectable)', 'Igual que otros AINEs. Contraindicado en sangrado activo', '[]'::jsonb, NULL, TRUE, TRUE, 'Potencia analgésica comparable a morfina. Riesgo de sangrado GI elevado - NO combinar con anticoagulantes. Máximo 2 días por riesgo renal', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('bcd5b2a1-2919-4c52-ab14-4816cc94c226', '18', 'aine', 'Ketorolaco 30 mg/ml inyectable', NULL, 'Ampollas 30 mg/ml (1 ml)', 'Aplicar 30 mg IM/IV cada 8 horas (máximo 120 mg/día). Solo uso hospitalario o post-quirúrgico inmediato supervisado.', 'Contraindicado en menores de 16 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 2 días', 'Igual que Ketorolaco oral', '[]'::jsonb, NULL, TRUE, TRUE, 'Uso restringido a ámbito hospitalario. Riesgo de sangrado elevado', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('edea5852-31ab-42ce-8e3d-ac559e8c471b', '19', 'aine', 'Clonixinato de lisina 125 mg', NULL, 'Comprimidos 125 mg', 'Tomar 1-2 comprimidos cada 6-8 horas (máximo 375 mg/día). Alternativa a AINEs clásicos en dolor odontogénico.', 'No recomendado en menores de 12 años', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Úlcera péptica activa, hipersensibilidad', '[]'::jsonb, NULL, TRUE, TRUE, 'AINE de perfil intermedio. Menor evidencia que Ibuprofeno pero ampliamente usado en Latinoamérica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('985eb488-30da-4b9e-8afd-21d00773fb79', '20', 'aine', 'Clonixinato de lisina inyectable', NULL, 'Ampollas 100 mg/2 ml', 'Aplicar 100 mg IM cada 6-8 horas. Solo para dolor agudo supervisado.', 'No recomendado en menores de 12 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 2 días', 'Igual que Clonixinato oral', '[]'::jsonb, NULL, TRUE, TRUE, 'Uso en dolor agudo post-quirúrgico cuando no es posible vía oral', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5e55fc9a-3e07-422a-b17b-cf997b36c1f7', '21', 'aine', 'Naproxeno 250 mg', NULL, 'Comprimidos 250 mg', 'Tomar 1-2 comprimidos cada 12 horas con alimentos (máximo 1 g/día). Primera dosis puede ser doble.', 'Niños >2 años: 10 mg/kg/dosis cada 12 horas (máximo 15 mg/kg/día)', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Igual que otros AINEs clásicos', '[]'::jsonb, NULL, TRUE, TRUE, 'AINE de vida media larga (12-15 h) - permite dosificación cada 12 h. Útil en dolor inflamatorio persistente', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('1207f855-8b79-40a2-856f-5cbded9b1f33', '22', 'aine', 'Naproxeno 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 12 horas con alimentos (máximo 1 g/día).', 'No usar comprimido 500 mg en niños <40 kg', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Igual que Naproxeno 250 mg', '[]'::jsonb, NULL, TRUE, TRUE, 'Presentación de elección en adulto. Perfil similar a Ibuprofeno con dosificación más cómoda', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('41762a15-387b-4834-a97a-e9c2dd16c1e9', '23', 'cox2', 'Etoricoxib 90 mg', NULL, 'Comprimidos 90 mg', 'Tomar 1 comprimido cada 24 horas (máximo 90 mg/día). Para dolor post-quirúrgico agudo.', 'Contraindicado en menores de 16 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 3 días', 'Insuficiencia cardíaca, HTA no controlada, enfermedad coronaria, ACV previo, úlcera activa', '[]'::jsonb, NULL, TRUE, TRUE, 'Inhibidor selectivo COX-2. Menor riesgo GI pero mayor riesgo cardiovascular. Reservar para pacientes con contraindicación a AINEs clásicos por riesgo GI', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5df77a29-0b02-418f-aa0e-b62a19394b9c', '24', 'cox2', 'Celecoxib 200 mg', NULL, 'Cápsulas 200 mg', 'Tomar 1 cápsula cada 12 horas con alimentos (máximo 400 mg/día).', 'Contraindicado en menores de 18 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 7 días', 'Igual que Etoricoxib. Contraindicado en alergia a sulfas (reactividad cruzada)', '[]'::jsonb, NULL, TRUE, TRUE, 'Inhibidor selectivo COX-2. Precaución en alérgicos a sulfas. Alternativa en pacientes con riesgo GI alto', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a2a596a1-6bf5-4e52-aa88-298b2e037d4e', '25', 'opioide', 'Tramadol 50 mg', NULL, 'Comprimidos 50 mg / Gotas 100 mg/ml', 'Tomar 1-2 comprimidos cada 8-12 horas (máximo 400 mg/día, reducir a 300 mg/día en >75 años). Para dolor severo que no responde a AINEs.', 'Niños >12 años: 1-2 mg/kg/dosis cada 6-8 horas (máximo 8 mg/kg/día). Gotas 100 mg/ml: 1 gota = 5 mg.', NULL, NULL, NULL, NULL, NULL, 'Máximo 3-5 días', 'Depresión respiratoria, epilepsia no controlada, uso concomitante con ISRS (riesgo síndrome serotoninérgico), menores de 12 años', '[]'::jsonb, NULL, TRUE, TRUE, 'Opioide débil. Riesgo de náuseas, vómitos, mareos. NO combinar con Paracetamol si ya usa combinación fija. Prescribir con receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('1fd10bfe-cf07-4c89-994f-b60cfa2f6f40', '26', 'opioide', 'Tramadol 100 mg/ml gotas', NULL, 'Frasco gotas 100 mg/ml (10-20 ml)', 'Tomar 20-40 gotas cada 8-12 horas diluidas en agua (1 gota = 5 mg). Máximo 400 mg/día.', 'Niños >12 años: 1-2 mg/kg/dosis. Fórmula: 0.2-0.4 gotas/kg.', NULL, NULL, NULL, NULL, NULL, 'Máximo 3-5 días', 'Igual que Tramadol 50 mg', '[]'::jsonb, NULL, TRUE, TRUE, 'Presentación útil para dosificación flexible en ancianos o disfagia. Medir con cuentagotas incluido', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a22b0c7c-9b8f-4230-a145-259b8876d756', '27', 'opioide', 'Codeína + Paracetamol (30/500 mg)', NULL, 'Comprimidos combinación fija', 'Tomar 1-2 comprimidos cada 6-8 horas (máximo 6 comprimidos/día = 180 mg codeína + 3 g Paracetamol). Para dolor moderado a severo.', 'Contraindicado en menores de 12 años. Niños 12-18 años: solo bajo prescripción especializada.', NULL, NULL, NULL, NULL, NULL, 'Máximo 3 días', 'Depresión respiratoria, asma, menores de 12 años, lactancia, metabolizadores ultrarrápidos CYP2D6', '[]'::jsonb, NULL, TRUE, TRUE, 'Codeína es profármaco → morfina vía CYP2D6. Variabilidad genética puede causar toxicidad. Riesgo de estreñimiento - recomendar fibra e hidratación. Receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a1897da3-5daf-4757-a5e7-3a03b1cbbd2a', '28', 'opioide', 'Tramadol + Paracetamol (37.5/325 mg)', NULL, 'Comprimidos combinación fija', 'Tomar 1-2 comprimidos cada 8 horas (máximo 4 comprimidos/día = 150 mg Tramadol + 1.3 g Paracetamol).', 'Contraindicado en menores de 12 años', NULL, NULL, NULL, NULL, NULL, 'Máximo 3-5 días', 'Igual que Tramadol. No combinar con otros productos que contengan Paracetamol', '[]'::jsonb, NULL, TRUE, TRUE, 'Combinación sinérgica para dolor post-quirúrgico. Verificar que el paciente no use otro producto con Paracetamol para evitar hepatotoxicidad. Receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('74c8a1ea-f564-422d-85cb-a34ed7d55850', '29', 'opioide', 'Morfina 10 mg/ml inyectable', NULL, 'Ampollas 10 mg/ml', 'Uso exclusivamente hospitalario. Dosis según protocolo de urgencia.', 'Uso exclusivamente hospitalario', NULL, NULL, NULL, NULL, NULL, 'N/A', 'Uso hospitalario exclusivo', '[]'::jsonb, NULL, TRUE, TRUE, 'Reservado para manejo de urgencias médicas (edema agudo pulmonar, dolor severo traumático). No se prescribe en consulta odontológica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('7641f8bd-94ba-443f-b19c-5fb6b223d96b', '30', 'opioide', 'Petidina (Meperidina) 100 mg/2 ml', NULL, 'Ampollas 100 mg/2 ml', 'Uso exclusivamente hospitalario.', 'Uso exclusivamente hospitalario', NULL, NULL, NULL, NULL, NULL, 'N/A', 'Uso hospitalario exclusivo', '[]'::jsonb, NULL, TRUE, TRUE, 'Reservado para urgencias hospitalarias. No se prescribe en consulta odontológica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('8e77c9b3-2b3f-462c-8849-ec654b9629b9', '31', 'penicilina', 'Amoxicilina 500 mg', NULL, 'Comprimidos 500 mg / Cápsulas 500 mg / Suspensión 250 mg/5 ml', 'Tomar 1 comprimido cada 8 horas (500 mg c/8h) con o sin alimentos. Para infecciones odontogénicas agudas considerar 875 mg c/12h.', 'Niños <40 kg: 40-50 mg/kg/día dividido en 3 tomas (c/8h). Suspensión 250 mg/5 ml: 2.5 ml por cada 10 kg de peso, 3 veces al día. Máximo 1.5 g/día.', NULL, NULL, NULL, NULL, NULL, '7 días (5-10 según gravedad)', 'Hipersensibilidad a penicilinas (anafilaxia previa), mononucleosis infecciosa (riesgo de rash)', '[]'::jsonb, NULL, TRUE, TRUE, 'Antibiótico de primera línea en odontología. Completar tratamiento completo aunque mejoren síntomas. Tomar con probióticos para reducir diarrea asociada', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('e0d66879-249e-421e-96ee-6407b4eea4ef', '32', 'penicilina', 'Amoxicilina 1 g', NULL, 'Comprimidos 1000 mg', 'Tomar 1 comprimido cada 12 horas (1 g c/12h). Para infecciones severas o profilaxis pre-procedimiento (2 g dosis única 30-60 min antes).', 'No usar comprimido 1 g en niños <40 kg. Usar presentación pediátrica.', NULL, NULL, NULL, NULL, NULL, '7 días (profilaxis: dosis única)', 'Igual que Amoxicilina 500 mg', '[]'::jsonb, NULL, TRUE, TRUE, 'Dosis de 2 g única usada para profilaxis de endocarditis AHA 2021. Verificar protocolo en tab de Profilaxis', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('184ac3ca-921f-404e-9a93-4d922d663194', '33', 'penicilina', 'Amoxicilina suspensión 250 mg/5 ml', NULL, 'Frasco jarabe 250 mg/5 ml (100 ml)', 'No usar en adultos (dosis insuficiente)', 'Niños <40 kg: 40-50 mg/kg/día dividido en 3 tomas. Fórmula: 0.4 ml/kg/dosis (3 veces al día). Ej: niño 15 kg → 6 ml por toma. Máximo 1.5 g/día.', NULL, NULL, NULL, NULL, NULL, '7 días (5-10 según gravedad)', 'Hipersensibilidad a penicilinas (anafilaxia previa)', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Presentación pediátrica de elección. Agitar bien antes de usar. Medir con jeringa dosificadora. Refrigerar después de abierto (dura 14 días)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('04c44013-efe1-4f0d-bf45-e9aef29feb59', '34', 'penicilina', 'Amoxicilina + Ácido Clavulánico 500/125 mg', NULL, 'Comprimidos 500/125 mg / Suspensión 400/57 mg/5 ml', 'Tomar 1 comprimido cada 8 horas al inicio de las comidas (reduce molestias GI). Para infecciones odontogénicas con sospecha de betalactamasa.', 'Niños: 45 mg/kg/día de componente amoxicilina dividido en 3 tomas. Suspensión 400/57 mg/5 ml: 2.5 ml por cada 10 kg de peso, 3 veces al día.', NULL, NULL, NULL, NULL, NULL, '7-10 días', 'Hipersensibilidad a penicilinas, hepatitis colestásica previa por amoxicilina/clavulánico', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Reservado para infecciones refractarias a Amoxicilina sola o con sospecha de resistencia. Tomar con alimentos para reducir diarrea', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d8e82aa6-1988-4936-b90d-4dcb1b1f2cde', '35', 'penicilina', 'Amoxicilina + Ácido Clavulánico 875/125 mg', NULL, 'Comprimidos 875/125 mg / Suspensión 400/57 mg/5 ml', 'Tomar 1 comprimido cada 12 horas al inicio de las comidas. Dosis de elección para infecciones odontogénicas agudas severas.', 'No usar comprimido 875/125 en niños <40 kg. Usar presentación pediátrica.', NULL, NULL, NULL, NULL, NULL, '7-10 días', 'Igual que Amoxicilina + Ácido Clavulánico 500/125', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Presentación de elección en adulto. Dosificación cada 12 h mejora adherencia. Tomar siempre con alimentos', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('638a633a-eb3a-48cc-bc10-e76b820a480a', '36', 'penicilina', 'Ampicilina 500 mg', NULL, 'Cápsulas 500 mg / Inyectable 500 mg y 1 g', 'Tomar 1 cápsula cada 6 horas con el estómago vacío (1 hora antes o 2 horas después de comer). Alternativa a Amoxicilina en infecciones específicas.', 'Niños: 50-100 mg/kg/día dividido en 4 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a penicilinas', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Menor absorción oral que Amoxicilina. La presentación inyectable se usa para profilaxis de endocarditis (2 g IM/IV) cuando no es posible vía oral', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('c4203605-6127-44b1-a9db-3acc02e2c842', '37', 'penicilina', 'Penicilina V (Fenoximetilpenicilina) 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 6 horas con el estómago vacío. Para infecciones leves por estreptococos.', 'Niños: 25-50 mg/kg/día dividido en 4 tomas.', NULL, NULL, NULL, NULL, NULL, '7-10 días', 'Hipersensibilidad a penicilinas', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Alternativa histórica. Menor espectro que Amoxicilina. Uso limitado actualmente en odontología', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('8a81d2bc-4593-4cf3-9c81-2cc2457ca512', '38', 'penicilina', 'Penicilina G Benzatina 1.200.000 UI', NULL, 'Ampollas inyectables 1.200.000 UI', 'Aplicar 1.200.000 UI IM profunda (glúteo) dosis única. Para profilaxis de fiebre reumática o infecciones específicas por estreptococos.', 'Niños: 600.000-1.200.000 UI IM dosis única según peso.', NULL, NULL, NULL, NULL, NULL, 'Dosis única', 'Hipersensibilidad a penicilinas', '["penicilina"]'::jsonb, NULL, TRUE, TRUE, 'Aplicación intramuscular profunda exclusiva. No usar vía IV (riesgo de embolia). Dolor en sitio de inyección', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('3ee7d8ee-4dcf-4b51-a80e-9fe5d4f4ebbe', '39', 'lincosamida', 'Clindamicina 300 mg', NULL, 'Cápsulas 300 mg', 'Tomar 1 cápsula cada 8 horas con abundante agua (para reducir esofagitis). Alternativa de elección en alérgicos a penicilinas para infecciones odontogénicas.', 'Niños: 8-20 mg/kg/día dividido en 3-4 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a lincosamidas, antecedentes de colitis por C. difficile', '["lincosamida"]'::jsonb, NULL, TRUE, TRUE, 'Alta concentración en hueso y tejidos blandos. Riesgo de colitis pseudomembranosa por C. difficile - suspender si aparece diarrea severa. Tomar con un vaso completo de agua', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('c51a84b3-3ff5-4b30-9a2a-db9f2893d13d', '40', 'lincosamida', 'Clindamicina 600 mg/4 ml inyectable', NULL, 'Ampollas 600 mg/4 ml', 'Aplicar 600 mg IV cada 8-12 horas diluida en 100 ml de solución salina (mínimo 30 min de infusión). Uso hospitalario para infecciones severas.', 'Uso hospitalario pediátrico bajo supervisión', NULL, NULL, NULL, NULL, NULL, '7 días', 'Igual que Clindamicina oral', '["lincosamida"]'::jsonb, NULL, TRUE, TRUE, 'No aplicar IV directa (riesgo de paro cardíaco). Uso en infecciones odontogénicas severas con compromiso sistémico', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('2fd013b2-45f9-4967-9280-aa3015e0d6d6', '41', 'macrolido', 'Azitromicina 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 24 horas en ayunas (1 hora antes o 2 horas después de comer). Esquema corto de 3-5 días por vida media larga.', 'Niños: 10 mg/kg/día una vez al día por 3 días (máximo 500 mg/día).', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Hipersensibilidad a macrólidos, arritmias (prolongación QT)', '["macrolido"]'::jsonb, NULL, TRUE, TRUE, 'Ventaja: esquema corto mejora adherencia. Útil en alérgicos a penicilinas. Evitar en pacientes con prolongación QT conocida', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('e4103109-debd-4d4b-acd4-a4c295c3e044', '42', 'macrolido', 'Claritromicina 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 12 horas con alimentos. Para infecciones respiratorias y odontogénicas.', 'Niños: 15 mg/kg/día dividido en 2 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a macrólidos, uso concomitante con estatinas (riesgo rabdomiólisis)', '["macrolido"]'::jsonb, NULL, TRUE, TRUE, 'Inhibidor potente de CYP3A4. Interacciones con múltiples fármacos (estatinas, anticoagulantes, benzodiazepinas). Verificar tab de Interacciones', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('fcaccc63-0da1-4eee-8f74-156786e977f3', '43', 'macrolido', 'Eritromicina 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 6 horas con el estómago vacío. Alternativa histórica a penicilinas.', 'Niños: 40 mg/kg/día dividido en 4 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a macrólidos, arritmias', '["macrolido"]'::jsonb, NULL, TRUE, TRUE, 'Mayor incidencia de molestias GI que otros macrólidos. Uso limitado actualmente - preferir Azitromicina o Claritromicina', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('6b717d68-c386-4b66-9a61-a4ea256c652c', '44', 'nitroimidazol', 'Metronidazol 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 8 horas con alimentos. Combinar con Amoxicilina o Clindamicina para infecciones odontogénicas anaerobias (abscesos severos).', 'Niños: 30 mg/kg/día dividido en 3 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a nitroimidazoles, consumo de alcohol (efecto disulfiram), enfermedad hepática grave', '["nitroimidazol"]'::jsonb, NULL, TRUE, TRUE, 'PROHIBIDO alcohol durante tratamiento y 48 h después (efecto disulfiram: vómitos, taquicardia). Eficaz contra anaerobios. Combinación clásica: Amoxicilina + Metronidazol', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('bc5e4526-9b19-4175-a784-2f7d8a54bd73', '45', 'cefalosporina', 'Cefadroxilo 500 mg', NULL, 'Cápsulas 500 mg', 'Tomar 1 cápsula cada 12 horas con alimentos. Alternativa en pacientes con alergia leve a penicilinas (rash sin anafilaxia).', 'Niños: 30 mg/kg/día dividido en 2 tomas.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Hipersensibilidad a cefalosporinas, anafilaxia previa a penicilinas (reactividad cruzada 5-10%)', '["cefalosporina"]'::jsonb, NULL, TRUE, TRUE, 'Cefalosporina de primera generación. Precaución en alérgicos a penicilinas por reactividad cruzada. Verificar tab de Alergias Cruzadas', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('8b59fb16-f3e3-4e9f-9a4f-82cc2b959f3f', '46', 'cefalosporina', 'Cefalexina 500 mg', NULL, 'Cápsulas 500 mg / Suspensión 250 mg/5 ml', 'Tomar 1 cápsula cada 6 horas con alimentos. Para infecciones de piel y tejidos blandos.', 'Niños: 25-50 mg/kg/día dividido en 3-4 tomas. Suspensión 250 mg/5 ml: 1 ml por cada 5 kg de peso, 3-4 veces al día.', NULL, NULL, NULL, NULL, NULL, '7 días', 'Igual que Cefadroxilo', '["cefalosporina"]'::jsonb, NULL, TRUE, TRUE, 'Cefalosporina de primera generación. Usada para profilaxis de endocarditis en alérgicos a penicilinas sin anafilaxia (2 g dosis única)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('b45ef491-62b8-4458-9c1a-b8ee92ce4715', '47', 'tetraciclina', 'Doxiciclina 100 mg', NULL, 'Cápsulas 100 mg', 'Tomar 1 cápsula cada 12 horas el primer día, luego 1 cápsula cada 24 horas. Tomar con abundante agua y permanecer erguido 30 min (evitar esofagitis).', 'Contraindicado en menores de 8 años (tinción dental permanente)', NULL, NULL, NULL, NULL, NULL, '7 días', 'Menores de 8 años, embarazo, lactancia, hipersensibilidad a tetraciclinas', '["tetraciclina"]'::jsonb, NULL, TRUE, TRUE, 'Alternativa en alérgicos a penicilinas para profilaxis de endocarditis (100 mg dosis única). No combinar con antiácidos, lácteos, hierro (quelación reduce absorción)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('7d6f85f7-0720-4ef0-ab2b-c6750df83e9f', '48', 'quinolona', 'Ciprofloxacino 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 12 horas con abundante agua. Para infecciones específicas resistentes a otros antibióticos.', 'Contraindicado en menores de 18 años (riesgo de tendinopatía)', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Menores de 18 años, embarazo, lactancia, epilepsia, uso concomitante con teofilina', '["quinolona"]'::jsonb, NULL, TRUE, TRUE, 'Fluoroquinolona de amplio espectro. Riesgo de tendinitis y ruptura tendinosa. Reservar para infecciones sin alternativas. No es primera línea en odontología', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5702b900-6c1f-424f-8759-1d5ca0aef4ef', '49', 'quinolona', 'Levofloxacino 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 24 horas. Para infecciones respiratorias o urinarias específicas.', 'Contraindicado en menores de 18 años', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Igual que Ciprofloxacino', '["quinolona"]'::jsonb, NULL, TRUE, TRUE, 'Fluoroquinolona respiratoria. Uso limitado en odontología. Reservar para infecciones sin alternativas', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('c14ddbc5-c227-445f-ab66-710831e885d4', '50', 'quinolona', 'Moxifloxacino 400 mg', NULL, 'Comprimidos 400 mg', 'Tomar 1 comprimido cada 24 horas. Para infecciones respiratorias severas.', 'Contraindicado en menores de 18 años', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Igual que Ciprofloxacino. Contraindicado en prolongación QT', '["quinolona"]'::jsonb, NULL, TRUE, TRUE, 'Fluoroquinolona de espectro extendido. Mayor riesgo de prolongación QT. Uso muy limitado en odontología', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a34d9243-0fe0-48d2-a01c-5266b53993da', '51', 'corticoide', 'Dexametasona 4 mg comprimidos', NULL, 'Comprimidos 4 mg', 'Tomar 1 comprimido 1 hora antes de la cirugía o cada 24 horas por 2 días. Para reducir inflamación post-quirúrgica severa.', 'Niños: 0.08-0.3 mg/kg/día en dosis única o dividida.', NULL, NULL, NULL, NULL, NULL, '1-2 días', 'Infecciones activas no tratadas, úlcera péptica activa, diabetes descompensada, psicosis', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Corticoide de alta potencia. Uso corto post-quirúrgico (exodoncias de terceros molares, cirugía ortognática). No suspender abruptamente si uso >7 días', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('65d724e3-498d-432d-afc1-7e6f688fe750', '52', 'corticoide', 'Dexametasona 8 mg/2 ml inyectable', NULL, 'Ampollas 8 mg/2 ml', 'Aplicar 8 mg IM/IV dosis única perioperatoria. Para profilaxis de edema en cirugía oral mayor.', 'Niños: 0.1-0.3 mg/kg IM/IV dosis única', NULL, NULL, NULL, NULL, NULL, 'Dosis única', 'Igual que Dexametasona oral', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Aplicación perioperatoria para reducir edema post-quirúrgico. Efecto máximo a las 24-48 h', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('0d178764-b164-4a36-b9ce-915aeab284ec', '53', 'corticoide', 'Prednisona 5 mg', NULL, 'Comprimidos 5 mg', 'Tomar 1-2 comprimidos cada 12-24 horas según indicación. Para procesos inflamatorios subagudos.', 'Niños: 0.5-2 mg/kg/día dividido en 1-2 tomas.', NULL, NULL, NULL, NULL, NULL, '3-7 días (reducir gradualmente si >7 días)', 'Infecciones activas no tratadas, úlcera péptica activa', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Corticoide de potencia intermedia. Si uso >7 días, reducir dosis gradualmente para evitar insuficiencia suprarrenal', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('e9996d72-4d2c-46e8-8d70-358fe671e912', '54', 'corticoide', 'Prednisona 20 mg', NULL, 'Comprimidos 20 mg', 'Tomar 1 comprimido cada 24 horas por la mañana (simula ritmo circadiano). Para procesos inflamatorios moderados a severos.', 'No usar comprimido 20 mg en niños pequeños. Usar presentación de 5 mg.', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Igual que Prednisona 5 mg', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Presentación de elección en adulto. Tomar por la mañana con alimentos para reducir molestias GI y respetar ritmo circadiano', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('880faa6a-9056-4b56-b904-51e964ba53f6', '55', 'corticoide', 'Betametasona 4 mg', NULL, 'Comprimidos 4 mg', 'Tomar 1 comprimido cada 24 horas por la mañana. Para procesos alérgicos o inflamatorios.', 'Niños: 0.02-0.3 mg/kg/día', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Igual que otros corticoides', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Corticoide de alta potencia. Uso en reacciones alérgicas y procesos inflamatorios severos', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('4ac5f867-7864-4269-8c9c-3b25a5189c0f', '56', 'corticoide', 'Hidrocortisona 100 mg inyectable', NULL, 'Ampollas 100 mg/2 ml', 'Uso hospitalario. Aplicar 100 mg IV/IM en reacciones alérgicas severas o insuficiencia suprarrenal aguda.', 'Uso hospitalario pediátrico', NULL, NULL, NULL, NULL, NULL, 'Dosis única o según protocolo', 'Uso hospitalario exclusivo', '["corticoide"]'::jsonb, NULL, TRUE, TRUE, 'Corticoide de baja potencia. Reservado para urgencias médicas (anafilaxia como coadyuvante, crisis suprarrenal). No se prescribe en consulta odontológica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('ce18fd6e-f884-424f-b1ba-b222ad6573aa', '57', 'antihistaminico', 'Clorfenamina 4 mg', NULL, 'Comprimidos 4 mg', 'Tomar 1 comprimido cada 6-8 horas. Para reacciones alérgicas leves. Causa somnolencia - no conducir.', 'Niños >6 años: 1 mg cada 6-8 horas', NULL, NULL, NULL, NULL, NULL, '3-5 días', 'Glaucoma de ángulo cerrado, hipertrofia prostática, menores de 2 años', '["antihistaminico"]'::jsonb, NULL, TRUE, TRUE, 'Antihistamínico de primera generación. Causa somnolencia significativa. Útil en reacciones alérgicas leves y como coadyuvante en anafilaxia', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a361f559-2780-4bde-98fe-8a76070167ce', '58', 'antihistaminico', 'Loratadina 10 mg', NULL, 'Comprimidos 10 mg', 'Tomar 1 comprimido cada 24 horas. Para reacciones alérgicas leves sin somnolencia.', 'Niños 2-12 años: 5 mg cada 24 horas (<30 kg) o 10 mg cada 24 horas (>30 kg)', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Hipersensibilidad', '["antihistaminico"]'::jsonb, NULL, TRUE, TRUE, 'Antihistamínico de segunda generación. No causa somnolencia significativa. Preferido sobre Clorfenamina en uso diurno', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d6644edd-61c6-4d1d-ba79-413ef8477435', '59', 'antihistaminico', 'Cetirizina 10 mg', NULL, 'Comprimidos 10 mg', 'Tomar 1 comprimido cada 24 horas por la noche. Para reacciones alérgicas leves.', 'Niños 2-6 años: 2.5 mg cada 24 horas. Niños 6-12 años: 5 mg cada 24 horas.', NULL, NULL, NULL, NULL, NULL, '3-7 días', 'Hipersensibilidad, insuficiencia renal grave', '["antihistaminico"]'::jsonb, NULL, TRUE, TRUE, 'Antihistamínico de segunda generación. Leve somnolencia en algunos pacientes. Alternativa a Loratadina', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('40eb30c2-5968-4138-8cf2-789c0e247a0f', '60', 'ansiolitico', 'Diazepam 5 mg', NULL, 'Comprimidos 5 mg', 'Tomar 1-2 comprimidos 1 hora antes del procedimiento odontológico en pacientes con ansiedad dental severa. Dosis única pre-procedimiento.', 'Niños >6 años: 0.1-0.3 mg/kg dosis única pre-procedimiento', NULL, NULL, NULL, NULL, NULL, 'Dosis única (uso puntual)', 'Depresión respiratoria, miastenia gravis, apnea del sueño, glaucoma de ángulo cerrado, menores de 6 años', '["ansiolitico"]'::jsonb, NULL, TRUE, TRUE, 'Benzodiazepina de vida media larga. Uso puntual para sedación mínima pre-procedimiento. Requiere acompañante para el regreso a casa. No conducir después. Receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d3ae9598-a2f0-48a1-9dc0-a0796a0fe109', '61', 'ansiolitico', 'Midazolam 7.5 mg', NULL, 'Comprimidos 7.5 mg', 'Tomar 1 comprimido 30-60 min antes del procedimiento. Para sedación mínima pre-procedimiento en adultos con ansiedad severa.', 'Uso hospitalario pediátrico bajo supervisión', NULL, NULL, NULL, NULL, NULL, 'Dosis única', 'Depresión respiratoria, apnea del sueño, miastenia gravis', '["ansiolitico"]'::jsonb, NULL, TRUE, TRUE, 'Benzodiazepina de vida media corta. Efecto rápido (15-30 min). Interacción con azoles (Fluconazol, Miconazol) aumenta sedación. Verificar tab de Interacciones. Receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('f65ae558-aa96-4ac4-ac6d-621723fc0e09', '62', 'ansiolitico', 'Alprazolam 0.5 mg', NULL, 'Comprimidos 0.5 mg', 'Tomar 1 comprimido 1 hora antes del procedimiento en pacientes con ansiedad dental. Dosis única pre-procedimiento.', 'No recomendado en menores de 18 años', NULL, NULL, NULL, NULL, NULL, 'Dosis única (uso puntual)', 'Depresión respiratoria, miastenia gravis, apnea del sueño', '["ansiolitico"]'::jsonb, NULL, TRUE, TRUE, 'Benzodiazepina de vida media corta. Uso puntual para ansiedad dental. Requiere acompañante. No conducir después. Receta retenida según normativa local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('38afa8cb-4082-4348-adf6-b1941360206f', '63', 'antiseptico', 'Clorhexidina 0.12% colutorio', NULL, 'Frasco 250 ml', 'Realizar buches con 15 ml durante 1 minuto, 2 veces al día (mañana y noche después del cepillado). No enjuagar con agua después.', 'Mayores de 6 años: 10 ml durante 1 minuto, 2 veces al día. Supervisado por adulto.', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad a clorhexidina', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Antiséptico de elección post-cirugía oral y en periodontitis. Uso máximo 14 días para evitar tinción dental. No usar inmediatamente después del cepillado (esperar 30 min)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('f628025f-bf56-4039-bfde-77d6e37b88fa', '64', 'antiseptico', 'Clorhexidina 0.2% gel', NULL, 'Tubo gel 30 g', 'Aplicar con hisopo o dedo limpio sobre la zona afectada 2-3 veces al día. Para gingivitis localizada o post-exodoncia.', 'Mayores de 6 años: aplicar con supervisión de adulto', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad a clorhexidina', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Presentación tópica para aplicación localizada. Útil en zonas de difícil acceso con colutorio', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('e792e8f6-ef2d-4df4-8ab9-3dddaefe4b0b', '65', 'antiseptico', 'Povidona yodada 10%', NULL, 'Frasco solución 120 ml', 'Aplicar con gasa estéril sobre piel o mucosa para desinfección pre-quirúrgica. Dejar actuar 1-2 minutos.', 'Precaución en menores de 2 años por riesgo de hipotiroidismo', NULL, NULL, NULL, NULL, NULL, 'Uso puntual', 'Alergia a yodo, hipertiroidismo, menores de 2 años (uso prolongado)', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Antiséptico amplio espectro. Precaución en alérgicos a yodo. No usar en heridas extensas por absorción sistémica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('86ea0491-7e19-4e50-90e4-676cb560676d', '66', 'antiseptico', 'Peróxido de hidrógeno 3% (agua oxigenada)', NULL, 'Frasco 100 ml', 'Diluir al 50% con agua (1.5%) y realizar buches durante 30 segundos, 2-3 veces al día. Para gingivitis ulcerativa o limpieza de heridas.', 'No usar en menores de 3 años. Mayores de 3 años: diluir al 50% y usar con supervisión', NULL, NULL, NULL, NULL, NULL, 'Máximo 7 días', 'Uso prolongado puede dañar tejido gingival', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Antiséptico oxidante. Uso limitado a corto plazo. La concentración al 3% sin diluir puede irritar mucosa. Uso principalmente para desbridamiento mecánico', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('c2afb0c1-c306-4c60-9abd-7830b358b8be', '67', 'preventivo', 'Fluoruro de sodio 0.05% colutorio', NULL, 'Frasco 250 ml', 'Realizar buches con 10 ml durante 1 minuto, 1 vez al día (preferiblemente noche). No enjuagar con agua después. No tragar.', 'Mayores de 6 años: 10 ml durante 1 minuto, 1 vez al día. Supervisado por adulto.', NULL, NULL, NULL, NULL, NULL, 'Uso continuo (preventivo)', 'Menores de 6 años (riesgo de fluorosis), hipersensibilidad', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Prevención de caries en pacientes de alto riesgo. Uso diario domiciliario. Complementa el cepillado con pasta fluorada', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('b1c71ff3-f408-4130-b738-44d3b05225a3', '68', 'preventivo', 'Fluoruro de sodio 1.23% gel profesional', NULL, 'Gel profesional aplicación en consulta', 'Aplicar en cubetas durante 4 minutos en consulta odontológica, 2-4 veces al año según riesgo de caries.', 'Aplicación profesional supervisada por odontólogo', NULL, NULL, NULL, NULL, NULL, 'Aplicación profesional', 'Menores de 6 años (preferir barniz fluorado en niños pequeños)', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Aplicación profesional exclusiva. No usar en casa. Para pacientes de alto riesgo de caries. Complementa medidas preventivas domiciliarias', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('2bd47064-722f-4f69-ab50-8752ec6afde7', '69', 'protector_gastrico', 'Omeprazol 20 mg', NULL, 'Cápsulas 20 mg', 'Tomar 1 cápsula cada 24 horas en ayunas (30 min antes del desayuno). Para gastroprotección en pacientes con AINEs o antecedentes de úlcera.', 'Niños >1 año: 0.5-1 mg/kg/día (máximo 20 mg/día)', NULL, NULL, NULL, NULL, NULL, '7-14 días (o mientras dure el AINE)', 'Hipersensibilidad', '["protector_gastrico"]'::jsonb, NULL, TRUE, TRUE, 'Inhibidor de bomba de protones. Prescribir junto con AINEs en pacientes de riesgo GI. Uso a corto plazo preferiblemente', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('0db3d52c-095e-499a-9846-e0ca74c26a06', '70', 'protector_gastrico', 'Ranitidina 150 mg', NULL, 'Comprimidos 150 mg', 'Tomar 1 comprimido cada 12 horas. Alternativa a Omeprazol en gastroprotección.', 'Niños: 2-4 mg/kg/dosis cada 12 horas', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad', '["protector_gastrico"]'::jsonb, NULL, TRUE, TRUE, 'Antagonista H2. Nota: retirada del mercado en varios países por impurezas (NDMA). Verificar disponibilidad local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('ab32d697-8cca-4257-befb-2aae857dd85a', '71', 'hemostatico', 'Ácido tranexámico 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 2 comprimidos cada 8 horas (1 g c/8h) comenzando 24 h antes de cirugía en pacientes anticoagulados, continuar 2-3 días post.', 'Niños: 25 mg/kg/dosis cada 8 horas', NULL, NULL, NULL, NULL, NULL, '2-5 días', 'Trombosis activa, insuficiencia renal grave', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Antifibrinolítico. Coadyuvante en control de sangrado post-quirúrgico. Especialmente útil en pacientes anticoagulados que no suspenden medicación', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('25d99ec1-e0cc-4016-bb75-afacb9e97004', '72', 'hemostatico', 'Ácido tranexámico 500 mg/5 ml inyectable', NULL, 'Ampollas 500 mg/5 ml', 'Aplicar 500-1000 mg IV lenta (mínimo 10 min) o IM. Uso hospitalario o perioperatorio supervisado.', 'Niños: 10 mg/kg IV/IM', NULL, NULL, NULL, NULL, NULL, 'Dosis única o según protocolo', 'Igual que Ácido tranexámico oral', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Uso perioperatorio en cirugía oral con riesgo de sangrado. Aplicación IV lenta obligatoria', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('131deedc-7c6c-4392-a3b6-7f8e731889b8', '73', 'hemostatico', 'Adrenalina tópica 1:1000', NULL, 'Ampollas 1 mg/ml', 'Aplicar con gasa empapada sobre el sitio de sangrado durante 2-5 minutos. Uso local exclusivo para hemostasia.', 'Uso supervisado por profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación puntual', 'Hipertensión no controlada, arritmias, hipertiroidismo', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Uso local exclusivo para hemostasia. NO aplicar IV. Absorción sistémica mínima en aplicación tópica local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('bef6ccbd-2023-44f1-a0b9-0cb4257e2067', '74', 'hemostatico', 'Esponja de gelatina absorbible (Gelfoam)', NULL, 'Esponjas estériles', 'Colocar en el alvéolo post-exodoncia y comprimir. Se absorbe en 4-6 semanas. Coadyuvante en hemostasia local.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación puntual', 'N/A', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Material hemostático absorbible. Se coloca en el alvéolo y se satura con trombina o solución salina. No requiere retiro', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('a593fdcb-e280-4a33-8bed-0a1f588ee5b8', '75', 'hemostatico', 'Colágeno oxidado (Surgicel)', NULL, 'Láminas estériles', 'Aplicar sobre el sitio de sangrado y comprimir. Se absorbe en 7-14 días.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación puntual', 'N/A', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Material hemostático de origen celulósico. Útil en sangrado capilar y venoso. Se degrada completamente', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5680d990-6b29-43a7-8d3a-4345c5079789', '76', 'hemostatico', 'Cera de hueso', NULL, 'Sobres estériles', 'Aplicar sobre superficies óseas sangrantes durante cirugía. Uso mecánico para tamponar.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación puntual', 'N/A', '["hemostatico"]'::jsonb, NULL, TRUE, TRUE, 'Hemostático mecánico para hueso. Se aplica presionando sobre el sitio de sangrado óseo. No se absorbe', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('8bbd0b7e-cc39-46c7-87eb-fabd3a811a3d', '77', 'preventivo', 'Fluoruro de estaño 0.4% gel domiciliario', NULL, 'Gel 0.4% (frasco 50 ml)', 'Aplicar con cepillo suave 1 vez al día (noche) durante 1 minuto, no enjuagar. Para pacientes de alto riesgo de caries o sensibilidad.', 'Mayores de 6 años: aplicar con supervisión de adulto', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Menores de 6 años', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Prevención de caries y sensibilidad dentinaria. Uso domiciliario bajo indicación profesional', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5136ce00-7382-4a76-93f4-be9ed3617158', '78', 'antifungico_azol', 'Nistatina suspensión 100.000 UI/ml', NULL, 'Frasco 60 ml', 'Aplicar 4-6 ml en la boca y mantener 5 minutos antes de tragar, 4 veces al día después de comer. Para candidiasis oral.', 'Lactantes: 1-2 ml aplicados en mucosa oral 4 veces al día', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad', '["antifungico_azol"]'::jsonb, NULL, TRUE, TRUE, 'Antifúngico tópico de elección en candidiasis oral (muguet). No se absorbe sistémicamente. Mantener en boca el mayor tiempo posible antes de tragar', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d897637e-4a4c-4c18-bd6e-3f8c79d7f0b9', '79', 'antifungico_azol', 'Fluconazol 150 mg', NULL, 'Cápsulas 150 mg', 'Tomar 1 cápsula cada 24 horas el primer día (dosis de carga 200 mg), luego 100-150 mg cada 24 horas. Para candidiasis oral resistente a tratamiento tópico.', 'Niños: 3-6 mg/kg/día', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad a azoles, uso concomitante con terfenadina/cisaprida', '["antifungico_azol"]'::jsonb, NULL, TRUE, TRUE, 'Antifúngico sistémico. Inhibidor potente de CYP3A4 - múltiples interacciones (benzodiazepinas, anticoagulantes). Verificar tab de Interacciones', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5fe84dca-cd61-4a87-8f1f-b2f95b0e2e75', '80', 'antifungico_azol', 'Miconazol gel oral 2%', NULL, 'Tubo gel oral 40 g', 'Aplicar 2.5 ml (1/2 cucharadita) sobre las lesiones 4 veces al día después de comer. Mantener en boca el mayor tiempo posible.', 'Lactantes >4 meses: 1.25 ml aplicados 4 veces al día', NULL, NULL, NULL, NULL, NULL, '7-14 días', 'Hipersensibilidad a azoles, menores de 4 meses', '["antifungico_azol"]'::jsonb, NULL, TRUE, TRUE, 'Antifúngico tópico oral. Alternativa a Nistatina. Inhibe CYP3A4 - precaución con warfarina (aumenta INR). Verificar tab de Interacciones', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('85127520-2175-4031-bb7b-30e03a2ab541', '81', 'antiviral', 'Aciclovir 400 mg', NULL, 'Comprimidos 400 mg', 'Tomar 1 comprimido 5 veces al día (cada 4 horas omitiendo la noche) por 5 días para herpes labial primario. Para recurrencias: iniciar en pródromo.', 'Niños >2 años: 20 mg/kg/dosis 4 veces al día (máximo 800 mg/dosis)', NULL, NULL, NULL, NULL, NULL, '5 días (primoinfección) / 3-5 días (recurrencia)', 'Hipersensibilidad, insuficiencia renal grave', '["antiviral"]'::jsonb, NULL, TRUE, TRUE, 'Antiviral para herpes simple oral. Mayor eficacia si se inicia en las primeras 48-72 h o en fase prodrómica', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('5385f50b-d341-417d-bd1e-3cb4e82f023f', '82', 'antiviral', 'Valaciclovir 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 2 comprimidos cada 12 horas por 1 día (4 dosis) para herpes labial recurrencias. Esquema corto de alta eficacia.', 'No recomendado en menores de 12 años para herpes labial', NULL, NULL, NULL, NULL, NULL, '1 día (recurrencias)', 'Hipersensibilidad, insuficiencia renal grave', '["antiviral"]'::jsonb, NULL, TRUE, TRUE, 'Profármaco de Aciclovir con mejor biodisponibilidad. Esquema ultra-corto (1 día) mejora adherencia. Preferido sobre Aciclovir por comodidad', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('4d362987-b60b-428f-8735-764bab8a245a', '83', 'preventivo', 'Vitamina C 500 mg', NULL, 'Comprimidos 500 mg', 'Tomar 1 comprimido cada 24 horas. Suplemento antioxidante general.', 'Niños: 100-200 mg/día', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Cálculos renales, hemocromatosis', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Suplemento dietario. Sin indicación odontológica específica. Uso general como antioxidante', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('d1be2d5c-d240-40d0-a7ab-4d926c9a94db', '84', 'preventivo', 'Suplemento de calcio + vitamina D', NULL, 'Comprimidos combinación', 'Tomar 1 comprimido cada 24 horas con alimentos. Suplemento óseo general.', 'Según indicación pediátrica específica', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Hipercalcemia, sarcoidosis', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Suplemento óseo. Relevancia en pacientes con riesgo de osteoporosis que toman antirresortivos. Verificar tab de Antirresortivos', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('9a5548be-6be7-43b8-acd2-3cce32696a2b', '85', 'preventivo', 'Saliva artificial (spray/gel)', NULL, 'Spray o gel 50 ml', 'Aplicar en mucosa oral según necesidad, varias veces al día. Para xerostomía (boca seca).', 'Uso según necesidad', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'N/A', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Lubricante oral para pacientes con xerostomía (síndrome de Sjögren, radioterapia, medicamentos). Mejora comodidad y reduce riesgo de caries', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('09ed65f7-7341-4c4f-ad72-06ec5fb903f6', '86', 'preventivo', 'Pilocarpina 5 mg', NULL, 'Comprimidos 5 mg', 'Tomar 1 comprimido 3 veces al día con alimentos. Para xerostomía severa por radioterapia o Sjögren.', 'No recomendado en menores de 18 años', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Asma no controlada, glaucoma de ángulo cerrado, bradicardia', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Agente colinérgico que estimula producción salival. Efectos adversos: sudoración, náuseas, frecuencia urinaria. Uso especializado', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('68617136-9bd2-4b92-aa1c-6357c1e1cd46', '87', 'antiseptico', 'Cloruro de cetilpiridinio 0.05% colutorio', NULL, 'Frasco 250 ml', 'Realizar buches con 15 ml durante 30 segundos, 2 veces al día. Alternativa a Clorhexidina para uso prolongado.', 'Mayores de 6 años: usar con supervisión de adulto', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Hipersensibilidad', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Antiséptico de menor potencia que Clorhexidina. Útil para uso diario prolongado sin riesgo de tinción dental', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('0c3cd40e-5ead-4204-af7b-c663c218b872', '88', 'antiseptico', 'Triclosán 0.3% dentífrico', NULL, 'Tubo pasta dental 75 ml', 'Cepillar 2-3 veces al día con pasta que contiene Triclosán. Para control de placa y gingivitis.', 'Mayores de 6 años: usar con supervisión de adulto', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Hipersensibilidad', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Agente antibacteriano en pasta dental. Nota: retirado del mercado en algunos países por preocupaciones ambientales. Verificar disponibilidad local', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('b1c63370-14d7-43b2-9420-8f2934d0426e', '89', 'preventivo', 'Xilitol chicles/goma', NULL, 'Chicles con xilitol', 'Masticar 1-2 chicles durante 10-20 minutos después de las comidas, 3-5 veces al día. Para prevención de caries.', 'Mayores de 5 años: usar con supervisión de adulto', NULL, NULL, NULL, NULL, NULL, 'Uso continuo', 'Menores de 5 años (riesgo de atragantamiento)', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Edulcorante no cariogénico que inhibe crecimiento de S. mutans. Complementa medidas preventivas. No reemplaza el cepillado', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('838444af-0799-4422-ae52-d08aca5125c7', '90', 'preventivo', 'Hidróxido de calcio pasta', NULL, 'Pasta uso endodóntico (jeringa 2 g)', 'Uso profesional endodóntico. Aplicar en conducto radicular como medicación entre citas.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación profesional', 'Uso profesional exclusivo', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Material de uso endodóntico exclusivo. Inductor de dentina reparativa. No se prescribe al paciente', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('b7331068-f75e-413a-b37d-c59bf7169953', '91', 'preventivo', 'Óxido de zinc eugenol', NULL, 'Cemento provisorio (polvo + líquido)', 'Uso profesional. Preparar y aplicar como restauración provisoria entre citas.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación profesional', 'Uso profesional exclusivo, hipersensibilidad a eugenol', '["preventivo"]'::jsonb, NULL, TRUE, TRUE, 'Cemento provisorio de uso odontológico. Sellado temporal de cavidades. No se prescribe al paciente', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('f9593d30-2dcd-4b23-8bb5-e0dc9fefb5a5', '92', 'antiseptico', 'Formocresol', NULL, 'Frasco uso endodóntico pediátrico', 'Uso profesional en pulpotomía pediátrica. Aplicación tópica sobre pulpa cameral. En desuso - preferir alternativas.', 'Uso profesional pediátrico', NULL, NULL, NULL, NULL, NULL, 'Aplicación profesional', 'Uso profesional exclusivo', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Históricamente usado en pulpotomía pediátrica. Actualmente en desuso por preocupaciones de toxicidad. Preferir alternativas (MTA, sulfato férrico)', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('b5a394a4-14b1-47d2-b892-16dc824602b0', '93', 'antiseptico', 'Glutaraldehído 2%', NULL, 'Frasco desinfectante', 'Uso profesional para desinfección de instrumental. No usar en tejidos.', 'Uso profesional exclusivo', NULL, NULL, NULL, NULL, NULL, 'Uso profesional', 'Uso profesional exclusivo, hipersensibilidad', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Desinfectante de alto nivel para instrumental. No usar en tejidos por toxicidad. Manejar con guantes y ventilación adecuada', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum (id, numero, familia, nombre_generico, nombre_comercial, presentacion, posologia_adulto, posologia_pediatrica, dosis_max_adulto_mg, dosis_max_pediatrica_mg_por_kg, contenido_por_unidad_mg, volumen_por_unidad_ml, concentracion_mg_por_ml, duracion_dias, contraindicaciones, alergias_cruzadas, indicaciones, requiere_receta, activo, notas_especiales, fuente_revision, fecha_revision, curado_por) VALUES ('fff573cb-aa8a-454b-b503-ac57e6dd8d27', '94', 'antiseptico', 'Hipoclorito de sodio 5.25%', NULL, 'Frasco irrigación endodóntica', 'Uso profesional. Irrigar conducto radicular durante endodoncia con 2-5 ml por conducto.', 'Uso profesional', NULL, NULL, NULL, NULL, NULL, 'Aplicación profesional', 'Uso profesional exclusivo', '["antiseptico"]'::jsonb, NULL, TRUE, TRUE, 'Irrigante principal en endodoncia. Disuelve tejido orgánico y tiene acción antimicrobiana. No ingerir - uso exclusivo profesional', NULL, NULL, NULL) ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('7aa04d8c-8ef0-4d4d-9528-3fd5edcc1e11', NULL, '1', 'Adrenalina (Epinefrina)', '1:1000 (1 mg/ml)', 'Ampolla 1 ml / Autoinyector (EpiPen)', 'Anafilaxia / shock anafiláctico', '0.3-0.5 mg IM en cara anterolateral del muslo. Repetir cada 5-15 min si no mejora (máximo 3 dosis).', 'Niños <30 kg: 0.15 mg IM (autoinyector pediátrico). Niños >30 kg: 0.3 mg IM.', 'IM', 'PRIMERA LÍNEA en anafilaxia. Nunca IV directa a esta concentración. Llamar a urgencias inmediatamente después de administrar.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('4ba87cb9-e5f2-4a7f-b905-ca2cb4c451c6', NULL, '2', 'Nitroglicerina sublingual', '0.4 mg', 'Comprimidos sublinguales / Spray', 'Angina de pecho / dolor torácico de origen coronario', '1 comprimido sublingual cada 5 min (máximo 3 dosis). Si no mejora tras primera dosis, llamar a urgencias.', 'No usar en niños', 'Sublingual', 'Contraindicado si PAS <90 mmHg o uso reciente de sildenafil/tadalafil. Verificar presión arterial antes de administrar.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('f3a89b52-46a8-4319-9836-fccfffbf1822', NULL, '3', 'Salbutamol (Albuterol)', '100 mcg/dosis', 'Inhalador presurizado (MDI)', 'Broncoespasmo / crisis asmática', '2-4 inhalaciones (200-400 mcg). Repetir cada 20 min hasta 3 veces en primera hora si es necesario.', 'Niños: 1-2 inhalaciones con espaciador. Repetir cada 20 min si necesario.', 'Inhalatoria', 'Usar con espaciador en niños y ancianos. Si no mejora tras 3 aplicaciones, considerar urgencia médica.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('d68e3a81-12b1-459e-ba1f-d85ec4c2de1b', NULL, '4', 'Diazepam', '5 mg / 10 mg', 'Comprimidos / Solución rectal', 'Convulsiones prolongadas (>5 min)', '5-10 mg VO o rectal. Si persisten convulsiones tras 5 min, considerar segunda dosis.', 'Niños: 0.2-0.5 mg/kg rectal (máximo 10 mg).', 'VO/Rectal', 'Riesgo de depresión respiratoria. Monitorear vía aérea. Llamar a urgencias si convulsiones persisten.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('9421d8c9-550d-4c46-a880-37b51cac41e5', NULL, '5', 'Aspirina (Ácido acetilsalicílico)', '325 mg', 'Comprimidos masticables', 'Sospecha de infarto agudo de miocardio (IAM)', 'Masticar 160-325 mg (1/2 a 1 comprimido de 325 mg) lo antes posible.', 'No usar en niños (riesgo de síndrome de Reye)', 'Oral (masticar)', 'Contraindicado en alergia a AINEs, sangrado activo, úlcera activa. Masticar para absorción rápida.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('830aba06-7e0c-4869-afe1-84cef6152a2e', NULL, '6', 'Hidrocortisona', '100 mg/2 ml', 'Ampolla inyectable', 'Reacciones alérgicas severas / coadyuvante en anafilaxia', '100-200 mg IV/IM. Coadyuvante a Adrenalina (no la reemplaza).', 'Niños: 1-2 mg/kg IV/IM', 'IV/IM', 'Coadyuvante en anafilaxia - NUNCA reemplaza Adrenalina como primera línea. Efecto tardío (1-2 horas).', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('6b6dc0a2-7014-4e1a-ba83-e5de85da9175', NULL, '7', 'Clorfenamina', '10 mg/ml', 'Ampolla inyectable', 'Reacciones alérgicas leves / coadyuvante en anafilaxia', '10 mg IM/IV lenta. Coadyuvante en reacciones alérgicas.', 'Niños: 0.1-0.2 mg/kg IM', 'IM/IV', 'Causa somnolencia. Coadyuvante - no reemplaza Adrenalina en anafilaxia.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('8b8b6185-16ad-4c3a-b2a7-8a34ee4da964', NULL, '8', 'Glucosa 50% / Glucagón', 'Glucosa 50% (500 mg/ml) / Glucagón 1 mg', 'Ampolla glucosa / Vial glucagón', 'Hipoglucemia severa', 'Si consciente: glucosa oral. Si inconsciente con acceso IV: glucosa 50% 25-50 ml IV. Sin acceso IV: Glucagón 1 mg IM/SC.', 'Niños: glucosa 10% 2-5 ml/kg IV. Glucagón 0.5 mg (<25 kg) o 1 mg (>25 kg) IM.', 'IV/IM/SC', 'Verificar glucemia si es posible. Si inconsciente, NO dar nada por vía oral (riesgo aspiración).', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('54ed251c-205c-465e-991f-64872a41e4aa', NULL, '9', 'Oxígeno', '100%', 'Cilindro con mascarilla/cánula nasal', 'Soporte respiratorio / hipoxia', 'Aplicar a 6-8 litros/min por mascarilla en urgencias. Titular según saturación (objetivo >94%).', 'Niños: 2-4 litros/min por cánula nasal o mascarilla', 'Inhalatoria', 'Verificar que el cilindro esté cargado y la mascarilla bien ajustada. Monitorear saturación si hay pulsioxímetro.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('9f671a27-d001-4aa3-9801-28b9fa9bc8f8', NULL, '10', 'Atropina', '0.5 mg/ml', 'Ampolla inyectable', 'Bradicardia sintomática / síncope vasovagal severo', '0.5 mg IV lenta. Repetir cada 3-5 min si necesario (máximo 3 mg).', 'Niños: 0.02 mg/kg IV (mínimo 0.1 mg, máximo 0.5 mg)', 'IV', 'Uso en bradicardia sintomática. En síncope vasovagal simple, preferir posición de Trendelenburg y monitoreo.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_urgencia (id, user_id, numero, nombre_generico, concentracion, presentacion, indicacion, posologia_adulto, posologia_pediatrica, via_administracion, advertencias, activo, fuente_revision, fecha_revision, curado_por) VALUES ('86359e9f-aa30-4986-9105-839f1fc047d5', NULL, '11', 'Flumazenilo / Naloxona', 'Flumazenilo 0.1 mg/ml / Naloxona 0.4 mg/ml', 'Ampollas inyectables', 'Reversión de sedación por benzodiazepinas (Flumazenilo) o opioides (Naloxona)', 'Flumazenilo: 0.2 mg IV lenta, repetir cada 60 seg hasta 1 mg. Naloxona: 0.4 mg IV/IM/SC, repetir cada 2-3 min.', 'Uso hospitalario pediátrico bajo supervisión', 'IV/IM/SC', 'Flumazenilo contraindicado en pacientes con epilepsia o uso crónico de benzodiazepinas. Naloxona puede precipitar síndrome de abstinencia en usuarios crónicos de opioides.', TRUE, 'AHA / AAOMS / Protocolos de urgencia odontológica', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('95d38c20-8d04-46c8-ba68-295dc781994e', NULL, '1', 'Alendronato 70 mg semanal', 'bifosfonato_oral', 'VO, 1 vez/semana', '70 mg semanal en ayunas, 30 min antes del desayuno, con 240 ml de agua, permanecer erguido 30 min', 'Osteoporosis postmenopáusica, osteoporosis masculina, prevención de fracturas', 'bajo', 'No suspender. Procedimientos dentales simples pueden realizarse sin modificaciones. Verificar duración del tratamiento: si >4 años, considerar evaluación por médico tratante antes de cirugía electiva. Priorizar tratamiento conservador. Evitar extracciones múltiples simultáneas.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('e09ebd9a-4696-4385-a769-259a2a70bcdc', NULL, '2', 'Risedronato 35 mg semanal', 'bifosfonato_oral', 'VO, 1 vez/semana', '35 mg semanal en ayunas, 30 min antes del desayuno, con 240 ml de agua, permanecer erguido 30 min', 'Osteoporosis postmenopáusica, osteoporosis inducida por corticoides', 'bajo', 'No suspender. Procedimientos dentales simples pueden realizarse sin modificaciones. Verificar duración del tratamiento: si >4 años, considerar evaluación por médico tratante antes de cirugía electiva. Priorizar tratamiento conservador.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('c65f18ab-3600-4239-b4f4-21582dad2f62', NULL, '3', 'Ibandronato 150 mg mensual', 'bifosfonato_oral', 'VO, 1 vez/mes', '150 mg mensual en ayunas, 60 min antes del desayuno, con 240 ml de agua, permanecer erguido 60 min', 'Osteoporosis postmenopáusica', 'bajo', 'No suspender. Procedimientos dentales simples pueden realizarse sin modificaciones. Verificar duración del tratamiento: si >4 años, considerar evaluación por médico tratante antes de cirugía electiva. Priorizar tratamiento conservador.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('1eaa1b7b-68cf-41cb-bf2a-b590dc84436b', NULL, '4', 'Ácido Zoledrónico 5 mg IV', 'bifosfonato_iv', 'IV, 1 vez/año', '5 mg IV en infusión de 15 min, 1 vez/año', 'Osteoporosis, hipercalcemia maligna, metástasis óseas', 'alto', 'Alto riesgo de MRONJ. Interconsulta obligatoria con oncólogo/médico tratante antes de cualquier cirugía oral electiva. Evaluar telopéptido C-terminal (CTX) si está disponible. Priorizar tratamiento conservador. Evitar extracciones, implantes y cirugía periodontal. Si cirugía es inevitable: antibióticos profilácticos, cierre primario, seguimiento estrecho.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('f572c672-7064-471e-abef-6f3c58fc04ba', NULL, '5', 'Denosumab 60 mg SC', 'anti_rankl', 'SC, cada 6 meses', '60 mg SC cada 6 meses', 'Osteoporosis postmenopáusica de alto riesgo, pérdida ósea por terapia hormonal en cáncer', 'alto', 'Alto riesgo de MRONJ. Interconsulta obligatoria con oncólogo/médico tratante antes de cirugía oral electiva. A diferencia de bifosfonatos, efecto reversible (vida media ~6 meses). Coordinar timing de procedimiento con próxima dosis. Priorizar tratamiento conservador. Si cirugía es inevitable: antibióticos profilácticos, cierre primario, seguimiento estrecho.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.vademecum_antirresortivos (id, user_id, numero, nombre_generico, familia, via_administracion, dosis_habitual, indicacion, riesgo_mronj, manejo_odontologico, activo, fuente_revision, fecha_revision, curado_por) VALUES ('86ae1694-0f18-4ed1-ab76-286e9994a5b9', NULL, '6', 'Bevacizumab (Avastin) IV', 'antiangiogenico', 'IV, según protocolo oncológico', 'Dosis según protocolo oncológico (habitualmente 5-15 mg/kg cada 2-3 semanas)', 'Cáncer colorrectal, pulmonar, renal, glioblastoma (antiangiogénico)', 'alto', 'Alto riesgo de MRONJ por mecanismo antiangiogénico. Interconsulta obligatoria con oncólogo antes de cualquier procedimiento dental electivo. Priorizar tratamiento conservador. Evitar extracciones y cirugía oral. Si procedimiento es inevitable: coordinar con oncólogo timing respecto a ciclos de quimioterapia, antibióticos profilácticos, cierre primario.', TRUE, 'AAOMS Position Paper on MRONJ 2022', '2026-08-14', 'Miguel C. Diaz Rodriguez') ON CONFLICT (numero) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('2aa9938b-fae6-477a-97e9-bd98b6ea9a4d', NULL, 'aine', 'aine', 'critica', NULL, 'Contraindicación absoluta. Si alergia a un AINE, evitar todos los AINEs clásicos (Ibuprofeno, Ketoprofeno, Diclofenaco, Naproxeno, etc.). Alternativa: Paracetamol o COX-2 selectivos según evaluación.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('eb012c7f-6f2e-4c8c-b9c3-602f7a0ae918', NULL, 'aine', 'cox2', 'advertencia', 'Variable', 'Los inhibidores selectivos COX-2 (Celecoxib, Etoricoxib) generalmente son seguros en pacientes con hipersensibilidad a AINEs clásicos. Sin embargo, Celecoxib tiene grupo sulfonamida - precaución en alérgicos a sulfas. Etoricoxib no tiene grupo sulfa.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('b051e7cc-2f96-4d4c-aba2-30e71cf16b35', NULL, 'aine', 'paracetamol', 'advertencia', '<5%', 'El 95% de los pacientes con hipersensibilidad a AINEs toleran Paracetamol en dosis <1.000 mg/día. Paracetamol NO es un AINE clásico (no inhibe COX-1 periférica). Puede usarse con precaución en alérgicos a AINEs.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('7d02b836-fe52-4e20-a51b-e17f9e5400ee', NULL, 'anestesico_amida', 'anestesico_amida', 'critica', NULL, 'Muy raro (<1%): alergia verdadera a amidas es extremadamente infrecuente. Si confirmada, evitar todas las amidas. Las reacciones adversas suelen ser síncopes vasovagales o alergia a sulfitos del vasoconstrictor. Evaluación por alergólogo recomendada.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('ed955490-5013-42eb-9964-3d0757744bd8', NULL, 'anestesico_ester', 'anestesico_ester', 'critica', NULL, 'Contraindicación absoluta. Si alergia a un anestésico tipo éster (Benzocaína, Procaína, Tetracaína), evitar todos los ésteres por reactividad cruzada vía PABA. Alternativa: Anestésicos tipo amida (Lidocaína, Mepivacaína, Articaína).', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('370091f3-7e8b-4adb-ad82-a4e84354f202', NULL, 'antifungico_azol', 'antifungico_azol', 'critica', NULL, 'Contraindicación absoluta. Si alergia a un azol (Fluconazol, Miconazol, Ketoconazol), evitar todos los azoles. Alternativa: Nistatina tópica o Anfotericina B según indicación.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('8ca8b540-57b2-470a-99bd-3f77911eaebf', NULL, 'antiseptico', 'antiseptico', 'critica', NULL, 'Si alergia a Clorhexidina, evitar todos los productos con Clorhexidina (colutorios, geles, soluciones). Alternativa: Povidona yodada o Cloruro de cetilpiridinio.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('4755b6bd-c09b-4b11-ad4d-5b69266b328f', NULL, 'antiviral', 'antiviral', 'critica', NULL, 'Si alergia a Aciclovir, precaución con Valaciclovir (es profármaco de Aciclovir - evitar). Alternativa: Famciclovir con evaluación previa.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('0cf4121a-aaff-4f3c-a0ff-1509a80e7993', NULL, 'cefalosporina', 'cefalosporina', 'critica', NULL, 'Contraindicación absoluta. Si alergia a cualquier cefalosporina, evitar todas las cefalosporinas. Alternativa según tipo de reacción.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('89f216c4-c237-460d-9d10-8c0fb10ce2d5', NULL, 'cefalosporina', 'penicilina', 'advertencia', '5-10%', 'Reactividad cruzada bidireccional. Si alergia a cefalosporina, evaluar uso de penicilinas con precaución según tipo de reacción. Si fue anafilaxia, evitar penicilinas.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('ae3e9ef5-44c7-4e40-8583-61197382f840', NULL, 'corticoide', 'corticoide', 'critica', NULL, 'Raro: alergia verdadera a corticoides es infrecuente. Si confirmada, evitar el grupo específico. Diferenciar de reacciones a excipientes.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('1e70108a-330b-407e-8bb0-0559f94a36a6', NULL, 'cox2', 'aine', 'advertencia', 'Variable', 'Si alergia a COX-2 selectivos, los AINEs clásicos generalmente son seguros. Evaluar según tipo de reacción.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('61834fc9-884f-45fa-88cd-d69a0907570f', NULL, 'lincosamida', 'lincosamida', 'critica', NULL, 'Contraindicación absoluta. Si alergia a Clindamicina, evitar Lincomicina. Alternativa: Macrólidos o Metronidazol según indicación.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('b66e4087-b8d4-465a-994e-fcaf8c7782f0', NULL, 'macrolido', 'macrolido', 'critica', NULL, 'Contraindicación absoluta. Si alergia a un macrólido, evitar todos (Azitromicina, Claritromicina, Eritromicina). Alternativa: Clindamicina o Doxiciclina.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('37877f0d-37bc-4bce-b11f-27b91e13e976', NULL, 'nitroimidazol', 'nitroimidazol', 'critica', NULL, 'Contraindicación absoluta. Si alergia a Metronidazol, evitar Tinidazol y Secnidazol. Alternativa: Clindamicina para anaerobios.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('018a8610-5ec9-4c0f-8fbf-a03389309a3b', NULL, 'opioide', 'opioide', 'critica', NULL, 'Precaución: las reacciones a opioides suelen ser pseudoalérgicas (liberación de histamina) más que alergia verdadera. Si alergia verdadera confirmada, evitar el grupo. Evaluación por alergólogo recomendada.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('106c2dec-bffe-4879-b7a5-6e9fe066a93a', NULL, 'paracetamol', 'aine', 'advertencia', '<5%', 'Si alergia a Paracetamol, los AINEs generalmente son seguros (mecanismo diferente). Evaluar con precaución según tipo de reacción.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('7676adca-1830-4bc8-8236-32138a03cae3', NULL, 'paracetamol', 'paracetamol', 'critica', NULL, 'Contraindicación absoluta. Si alergia a Paracetamol, evitar todas las presentaciones incluyendo combinaciones (Codeína+Paracetamol, Tramadol+Paracetamol). Alternativa: AINEs si no hay contraindicación.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('7f09a94d-d4cb-4842-8577-f616b3c972aa', NULL, 'penicilina', 'cefalosporina', 'advertencia', '5-10%', 'Reactividad cruzada histórica del 10% con cefalosporinas de 1ª generación. Con cefalosporinas de 2ª, 3ª y 4ª generación la tasa real es <2%. Si la reacción a penicilina fue anafilaxia, evitar cefalosporinas. Si fue rash leve, cefalosporinas pueden usarse con precaución.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('e42e0b9d-740d-4599-a452-47a163874c12', NULL, 'penicilina', 'lincosamida', 'sin_relacion', NULL, 'No hay reactividad cruzada documentada entre penicilinas y lincosamidas (Clindamicina). Clindamicina es la alternativa de elección en alérgicos a penicilinas para infecciones odontogénicas.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('ce76499f-9d06-4448-9e00-90f3c341e4a6', NULL, 'penicilina', 'macrolido', 'sin_relacion', NULL, 'No hay reactividad cruzada entre penicilinas y macrólidos. Macrólidos (Azitromicina, Claritromicina) son alternativas seguras en alérgicos a penicilinas.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('37aed9bf-434b-4a98-8ea6-92bcf59b0a44', NULL, 'penicilina', 'nitroimidazol', 'sin_relacion', NULL, 'No hay reactividad cruzada entre penicilinas y nitroimidazoles (Metronidazol). Metronidazol puede usarse de forma segura en alérgicos a penicilinas.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('73b8f90f-33c4-4304-bed7-b12a750b4a77', NULL, 'penicilina', 'penicilina', 'critica', NULL, 'Contraindicación absoluta. Si alergia a cualquier penicilina, evitar todas las penicilinas. Alternativa: Clindamicina, Azitromicina o Cefalosporina según tipo de reacción.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('6e24ba3d-6bae-402e-951f-ace174d0b7d9', NULL, 'quinolona', 'quinolona', 'critica', NULL, 'Contraindicación absoluta. Si alergia a una fluoroquinolona, evitar todas (Ciprofloxacino, Levofloxacino, Moxifloxacino). Alternativa según indicación.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.alergias_cruzadas (id, user_id, familia_alergia, familia_farmaco, severidad, porcentaje_cruzado, nota_clinica, activo) VALUES ('720b5c8c-ae8a-4e62-9d1c-31d72ef26f97', NULL, 'tetraciclina', 'tetraciclina', 'critica', NULL, 'Contraindicación absoluta. Si alergia a Doxiciclina, evitar Tetraciclina y Minociclina. Alternativa: Macrólidos o Clindamicina.', TRUE) ON CONFLICT (familia_alergia, familia_farmaco) DO NOTHING;
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('db5e6506-4c42-4b56-9adc-800a085adcca', NULL, 'AINEs', 'IECA / ARA-II / Diuréticos', '"Triple whammy": vasoconstricción aferente + ↓ prostaglandinas + depleción de volumen → lesión renal aguda', 'Evitar la combinación. Si AINE es imprescindible, monitorizar función renal (creatinina) antes y después. Hidratación adecuada. Preferir Paracetamol.', 'moderada', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('3b77fa1c-a204-439a-b4e8-94fa5cf7c9e8', NULL, 'AINEs', 'Litio', '↓ excreción renal de litio → ↑ litemia → toxicidad por litio (temblor, confusión, arritmias)', 'Evitar AINEs en pacientes con litio. Preferir Paracetamol. Si AINE es imprescindible, monitorizar niveles de litio y ajustar dosis.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('24f41e9f-5a49-493c-817c-fceb7abab9fa', NULL, 'AINEs', 'Metotrexato', '↓ excreción renal de metotrexato → ↑ toxicidad (mielosupresión, mucositis, nefrotoxicidad)', 'Evitar AINEs en pacientes con metotrexato a dosis altas. A dosis bajas de metotrexato (reumatológicas), usar con precaución y monitorizar. Preferir Paracetamol.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('9e608c55-5c52-4f0c-baa0-70ec73f8ca8d', NULL, 'AINEs (Ibuprofeno, Ketoprofeno, Diclofenaco)', 'Anticoagulantes / Antiagregantes (Warfarina, AAS, Clopidogrel)', 'Inhibición de función plaquetaria + irritación GI → ↑ riesgo de sangrado gastrointestinal', 'Preferir Paracetamol como primera línea analgésica en pacientes anticoagulados. Si AINE es imprescindible, usar la menor dosis efectiva por el menor tiempo posible + gastroprotección (Omeprazol).', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('f9f359dc-2fd3-487f-ab3e-67868124ed4e', NULL, 'Azoles (Fluconazol, Miconazol, Ketoconazol)', 'Benzodiazepinas (Diazepam, Midazolam, Alprazolam)', 'Inhibición de CYP3A4 → ↑ niveles de benzodiazepina → sedación excesiva y depresión respiratoria', 'Reducir dosis de benzodiazepina si se combina con azoles. Monitorizar sedación. Preferir Lorazepam (no depende de CYP3A4) si se requiere benzodiazepina durante tratamiento con azoles.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('ad807eac-c81c-4f29-aa08-f28206b53db0', NULL, 'Azoles (Fluconazol, Miconazol)', 'Warfarina / Acenocumarol', 'Inhibición de CYP2C9 y CYP3A4 → ↑ INR → riesgo de sangrado', 'Verificar INR antes y durante el tratamiento con azoles. Reducir dosis de anticoagulante si es necesario. Preferir Nistatina tópica si es para candidiasis oral.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('1cd1d8e5-68ba-4462-b331-ef3eb41b3f3b', NULL, 'Claritromicina', 'Midazolam', 'Inhibición potente de CYP3A4 → ↑ niveles de Midazolam → sedación excesiva prolongada (hasta 3-4 veces la duración esperada)', 'Evitar Claritromicina en pacientes con Midazolam planificado. Preferir Azitromicina (menor interacción). Si Claritromicina es imprescindible, reducir dosis de Midazolam 50% y monitorizar sedación extendida.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('966fea4a-133d-4693-9627-a67c698d437a', NULL, 'Codeína / Tramadol', 'ISRS (Fluoxetina, Paroxetina)', 'Riesgo de síndrome serotoninérgico (agitación, hipertermia, taquicardia, mioclonías). Además, Fluoxetina y Paroxetina inhiben CYP2D6 → ↓ conversión de Codeína a morfina → ↓ eficacia analgésica', 'Evitar combinación. Si analgesia opioide es necesaria en paciente con ISRS, preferir Morfina (no requiere activación por CYP2D6) bajo supervisión médica. Considerar alternativas no opioides.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('28e07eb9-fb99-4eda-9da2-c52b6dc618b6', NULL, 'Corticoides sistémicos (Prednisona, Dexametasona)', 'AINEs', 'Efecto sinérgico en irritación GI → ↑ riesgo de úlcera péptica y sangrado gastrointestinal', 'Evitar la combinación si es posible. Si es imprescindible, usar gastroprotección (Omeprazol 20 mg/día) y limitar duración. Preferir Paracetamol como analgésico.', 'moderada', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('a115b72a-9f51-4d96-87ee-a79cf5f29811', NULL, 'Macrólidos (Claritromicina, Eritromicina)', 'Estatinas (Simvastatina, Atorvastatina)', 'Inhibición de CYP3A4 → ↑ niveles de estatina → riesgo de rabdomiólisis y miopatía', 'Preferir Azitromicina (menor interacción CYP3A4). Si debe usar Claritromicina/Eritromicina, suspender estatina durante el tratamiento o reducir dosis. Monitorizar síntomas musculares.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('f38d0d8f-a26a-4ceb-9fe8-78baad2910fb', NULL, 'Metronidazol', 'Alcohol', 'Efecto disulfiram: acumulación de acetaldehído → vómitos severos, taquicardia, hipotensión, cefalea', 'PROHIBIDO alcohol durante tratamiento y 48-72 horas después de la última dosis. Advertir explícitamente al paciente incluyendo productos con alcohol oculto (enjuagues bucales, jarabes).', 'moderada', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('1cbdb69c-4449-4762-9f17-902acf97d9f4', NULL, 'Metronidazol', 'Warfarina / Acenocumarol', 'Inhibición de CYP2C9 → ↑ INR → riesgo de sangrado', 'Verificar INR antes y durante el tratamiento. Reducir dosis de anticoagulante si es necesario. Preferir Amoxicilina + Clavulánico si no hay contraindicación.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('863e806f-ec91-4f94-821e-d796b4bbd2e9', NULL, 'Tetraciclinas / Doxiciclina', 'Antiácidos, lácteos, hierro, calcio', 'Quelación con cationes divalentes (Ca2+, Mg2+, Fe2+) → ↓ absorción del antibiótico → pérdida de eficacia', 'Espaciar la toma de tetraciclina al menos 2 horas de antiácidos, lácteos, suplementos de hierro o calcio. Tomar con agua y permanecer erguido 30 min.', 'moderada', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('05b5c645-3fae-4a56-a2e1-a5ad7b200eda', NULL, 'Vasoconstrictores (Epinefrina en anestésicos)', 'Betabloqueantes no selectivos (Propranolol)', 'Estimulación alfa sin oposición beta → crisis hipertensiva paradójica, bradicardia refleja', 'Limitar dosis de epinefrina (máximo 2 tubos con 1:100.000). Aspirar siempre antes de infiltrar. Preferir Mepivacaína sin vasoconstrictor en pacientes con betabloqueantes no selectivos.', 'mayor', TRUE);
INSERT INTO public.interacciones_farmacologicas (id, user_id, farmaco_a, farmaco_b, efecto, manejo, severidad, activo) VALUES ('2dd4ace4-ae93-4428-86e7-75ebca44bd2b', NULL, 'Vasoconstrictores (Epinefrina)', 'Antidepresivos tricíclicos (Amitriptilina, Imipramina)', 'Potenciación de efectos adrenérgicos → ↑ riesgo de arritmias e hipertensión', 'Limitar dosis de epinefrina (máximo 2 tubos). Aspirar siempre antes de infiltrar. Monitorear signos vitales durante el procedimiento.', 'moderada', TRUE);
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('15c0583f-dfcb-4081-ba1c-e4a53aa788fb', NULL, 'Vía oral disponible, sin alergia a penicilinas', 'Amoxicilina', '2 g VO dosis única', '50 mg/kg VO (máximo 2 g) dosis única', 'Primera línea AHA 2021. Administrar 30-60 minutos antes del procedimiento. Para procedimientos que involucran manipulación de tejido gingival, región periapical o perforación de mucosa oral.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('2a8e7cd6-3027-4cb3-a131-37377fe86042', NULL, 'Alergia a penicilinas vía parenteral (sin anafilaxia previa)', 'Cefazolina o Ceftriaxona (*)', '1 g IM/IV dosis única', '50 mg/kg IM/IV (máximo 1 g) dosis única', '(*) NO usar si antecedente de anafilaxia, angioedema o urticaria inmediata a penicilinas. En caso de anafilaxia previa, usar alternativa no betalactámica según indicación médica.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('6f907788-228f-4271-9b75-d3300ca1fcd2', NULL, 'Alergia a penicilinas vía oral (sin anafilaxia previa)', 'Cefalexina (*)', '2 g VO dosis única', '50 mg/kg VO (máximo 2 g) dosis única', '(*) NO usar si antecedente de anafilaxia, angioedema o urticaria inmediata a penicilinas por reactividad cruzada. Preferir Azitromicina o Doxiciclina en ese caso.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('7ce69496-1ff0-41b7-9345-d0b662fb183d', NULL, 'Alergia a penicilinas vía oral (mayores de 8 años)', 'Doxiciclina', '100 mg VO dosis única', '2.2 mg/kg VO (máximo 100 mg) dosis única', 'Alternativa en mayores de 8 años. Contraindicado en menores de 8 años por tinción dental permanente. Administrar 30-60 minutos antes del procedimiento.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('83421c68-0a8e-4210-a9ff-261a51819369', NULL, 'Vía oral no disponible, sin alergia a penicilinas', 'Ampicilina', '2 g IM/IV dosis única', '50 mg/kg IM/IV (máximo 2 g) dosis única', 'Alternativa cuando no es posible vía oral. Administrar 30-60 minutos antes del procedimiento.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('a5e36754-575b-4f66-ac77-663bbb8f9e20', NULL, 'Alergia a penicilinas vía oral', 'Azitromicina o Claritromicina', '500 mg VO dosis única', '15 mg/kg VO (máximo 500 mg) dosis única', 'Alternativa segura en alérgicos a penicilinas. Macrólidos sin reactividad cruzada con betalactámicos. Administrar 30-60 minutos antes del procedimiento.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.profilaxis_endocarditis (id, user_id, situacion, farmaco, dosis_adulto, dosis_pediatrica, nota, activo, fuente_revision) VALUES ('c3c1f91b-2764-4715-9fce-cdc4c6efe0f4', NULL, 'Alternativa IV/IM, sin alergia a penicilinas', 'Cefazolina o Ceftriaxona', '1 g IM/IV dosis única', '50 mg/kg IM/IV (máximo 1 g) dosis única', 'Alternativa parenteral. Cefazolina o Ceftriaxona según disponibilidad. Administrar 30-60 minutos antes del procedimiento.', TRUE, 'AHA Scientific Statement 2021 / ADA');
INSERT INTO public.manejo_anticoagulantes (id, user_id, farmaco_o_grupo, recomendacion, medidas_hemostasia, activo, fuente_revision) VALUES ('0ebf123e-17b0-4c8e-8b9c-0849bd6548f5', NULL, 'Warfarina / Acenocumarol (anticoagulantes cumarínicos)', 'NO suspender si INR ≤ 3.5-4.0 para cirugía dental simple. Verificar INR el día del procedimiento. Para procedimientos con mayor riesgo de sangrado, interconsulta con médico tratante para ajuste de dosis.', 'Verificar INR el día del procedimiento (rango terapéutico 2.0-3.5). Compresión local 20-30 minutos. Ácido tranexámico tópico (enjuague 5% 4 veces/día por 2-5 días). Suturas herméticas. Esponja absorbible. Evitar AINEs (preferir Paracetamol para analgesia).', TRUE, 'AHA/ACC, guías europeas');
INSERT INTO public.manejo_anticoagulantes (id, user_id, farmaco_o_grupo, recomendacion, medidas_hemostasia, activo, fuente_revision) VALUES ('28e25c27-e7ba-4d9c-8905-45cfa100b639', NULL, 'DOACs (Dabigatrán, Rivaroxabán, Apixabán, Edoxabán)', 'Para procedimientos de bajo riesgo (1-3 exodoncias simples, curetaje): NO suspender. Programar procedimiento en el valle de acción (omitir dosis de la mañana si es de toma matinal, o realizar procedimiento 12-24 h después de última dosis). Para procedimientos de mayor riesgo, interconsulta con médico tratante.', 'Compresión local 20-30 minutos. Ácido tranexámico tópico. Suturas herméticas. Esponja absorbible. Evitar AINEs (preferir Paracetamol). Verificar función renal (afecta aclaramiento de DOACs). Programar en valle de acción del fármaco.', TRUE, 'AHA/ACC, guías europeas');
INSERT INTO public.manejo_anticoagulantes (id, user_id, farmaco_o_grupo, recomendacion, medidas_hemostasia, activo, fuente_revision) VALUES ('3efe1908-6522-49b5-9c11-2d8d1c37af8a', NULL, 'Clopidogrel / Prasugrel / Ticagrelor (antiagregantes P2Y12)', 'NO suspender sin autorización del cardiólogo tratante. Para cirugía dental simple, el riesgo de sangrado es manejable localmente. La suspensión puede precipitar trombosis de stent coronario (riesgo vital).', 'Compresión local 20-30 minutos. Ácido tranexámico tópico. Suturas herméticas. Esponja absorbible. Si sangrado persistente, interconsulta con cardiólogo para evaluar suspensión temporal coordinada.', TRUE, 'AHA/ACC, guías europeas');
INSERT INTO public.manejo_anticoagulantes (id, user_id, farmaco_o_grupo, recomendacion, medidas_hemostasia, activo, fuente_revision) VALUES ('8b02dabe-87ed-4176-89f0-890ef2b08e68', NULL, 'Heparinas de bajo peso molecular (HBPM) - anticoagulación puente', 'Manejo EXCLUSIVO del médico tratante (cardiólogo/hematólogo). La anticoagulación puente se usa cuando se suspende warfarina para procedimientos de alto riesgo. El odontólogo debe coordinar timing del procedimiento con el médico tratante.', 'Coordinar con médico tratante el timing de la última dosis de HBPM (habitualmente suspender 12-24 h antes del procedimiento). Compresión local. Ácido tranexámico tópico. Suturas herméticas. Verificar que no haya dosis de HBPM en las 12 h previas al procedimiento.', TRUE, 'AHA/ACC, guías europeas');
INSERT INTO public.manejo_anticoagulantes (id, user_id, farmaco_o_grupo, recomendacion, medidas_hemostasia, activo, fuente_revision) VALUES ('ebfbd598-4df1-455d-bb4c-faec87dfced8', NULL, 'Aspirina (AAS) - prevención secundaria', 'NO suspender para procedimientos dentales simples (1-3 exodoncias no complejas, curetaje, cirugía de tejido blando limitado). La suspensión aumenta riesgo de evento tromboembólico mayor que el riesgo de sangrado dental.', 'Compresión local con gasa 20-30 minutos. Ácido tranexámico tópico (enjuague 5% o gasa empapada). Suturas herméticas si aplica. Esponja de gelatina absorbible (Gelfoam) en alvéolo. Evitar enjuagues vigorosos primeras 24 h.', TRUE, 'AHA/ACC, guías europeas');
INSERT INTO public.reference_data_meta (id, user_id, version, curado_por, fecha_curacion, fecha_proxima_revision, fuentes, total_farmacos, notas) VALUES ('2aef2252-4908-4e30-87d3-28733a5379be', NULL, 'v1.1', 'Miguel C. Diaz Rodriguez', '2026-08-14', '2027-08-14', ARRAY['ISP Chile', 'Guías Clínicas AUGE/GES MINSAL', 'Malamed SF - Handbook of Local Anesthesia 7th ed', 'AAPD Guidelines', 'Goodman & Gilman 13ª ed', 'AHA Scientific Statement 2021', 'AAOMS Position Paper MRONJ 2022', 'FDA PLLR 2015', 'ADA Oral Health Topics'], 111, 'Vademécum odontológico curado clínicamente. Incluye: 94 fármacos regulares, 11 de urgencia, 6 antirresortivos (MRONJ), matriz de alergias cruzadas, interacciones, profilaxis endocarditis AHA, manejo anticoagulantes. Revisión anual programada.');
